konsole_tabs:
/* Generated by ~/.config/plasma-rice/rice.py from the wallpaper palette. Do not edit. */
QTabBar { background: rgba(6,15,32, 217); }
QTabBar::tab {
    background: transparent; color: #697b98;
    border: 1px solid transparent; border-radius: 10px;
    padding: 4px 12px; margin: 8px 2px 2px 2px;
    min-width: 7em; max-width: 22em;
}
QTabBar::tab:first { margin-left: 12px; }
QTabBar::tab:hover:!selected { background: rgba(214,226,246, 20); color: #a2b2cb; }
QTabBar::tab:selected {
    background: rgba(61,132,248, 41); color: #d6e2f6;
    border-color: rgba(61,132,248, 82);
}

zen:
/* Rice for Zen: generated by ~/.config/plasma-rice/apps.py from the wallpaper palette. Do not edit. */
:root, :host(:is(.anonymous-content-host, notification-message)) {
  --zen-primary-color: #3d84f8 !important;
  --zen-branding-dark: #060f20 !important;
  --zen-colors-primary: color-mix(in srgb, #3d84f8 22%, #091425) !important;
  --zen-colors-secondary: color-mix(in srgb, #3d84f8 32%, #091425) !important;
  --zen-colors-tertiary: #020919 !important;
  --zen-colors-hover-bg: color-mix(in srgb, #3d84f8 14%, #0d1829) !important;
  --zen-colors-primary-foreground: #d6e2f6 !important;
  --zen-colors-border: rgba(43,61,91, 0.55) !important;
  --zen-colors-border-contrast: rgba(43,61,91, 0.3) !important;
  --zen-colors-input-bg: #0d1829 !important;
  --zen-input-border-color: #2b3d5b !important;
  --zen-dialog-background: #091425 !important;
  --zen-urlbar-background: #0d1829 !important;
  --zen-main-browser-background: linear-gradient(135deg, rgba(14,43,92, 0.72) 0%, rgba(2,9,25, 0.84) 52%, rgba(8,47,82, 0.68) 100%) !important;
  --zen-main-browser-background-toolbar: linear-gradient(135deg, rgba(14,43,92, 0.72) 0%, rgba(2,9,25, 0.84) 52%, rgba(8,47,82, 0.68) 100%) !important;
  --toolbox-textcolor: #d6e2f6 !important;
  --toolbar-field-color: #d6e2f6 !important;
  --arrowpanel-background: #0d1829 !important;
  --arrowpanel-color: #d6e2f6 !important;
  --arrowpanel-border-color: rgba(43,61,91, 0.6) !important;
  --panel-separator-color: rgba(43,61,91, 0.6) !important;
  --focus-outline-color: #3d84f8 !important;
  --zen-sidebar-themed-icon-fill: #a2b2cb !important;
}

/* Zen paints the workspace gradient on these layers and sets its variables inline on them,
   so override the layers themselves (::before is the cross-fade target while switching spaces) */
.zen-browser-generic-background::after,
.zen-browser-generic-background::before {
  background: linear-gradient(135deg, rgba(14,43,92, 0.72) 0%, rgba(2,9,25, 0.84) 52%, rgba(8,47,82, 0.68) 100%) !important;
}

/* selected tab: a soft accent wash with a hairline, instead of plain white */
.tabbrowser-tab:is([selected], [multiselected]) .tab-background {
  background-color: rgba(61,132,248, 0.16) !important;
  box-shadow: inset 0 0 0 1px rgba(61,132,248, 0.32) !important;
}
.tabbrowser-tab:not([selected]):hover .tab-background {
  background-color: rgba(214,226,246, 0.07) !important;
}

/* command bar / url bar popup */
#urlbar[breakout-extend] > .urlbar-background,
#urlbar[breakout-extend] #urlbar-background {
  background-color: #0d1829 !important;
  border: 1px solid rgba(43,61,91, 0.7) !important;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.45) !important;
}
.urlbarView-row[selected] {
  background-color: rgba(61,132,248, 0.18) !important;
}

/* menus and popups */
menupopup, panel {
  --panel-background: #0d1829 !important;
  --panel-color: #d6e2f6 !important;
  --panel-border-color: rgba(43,61,91, 0.6) !important;
}
/* Rice for Zen: generated by ~/.config/plasma-rice/apps.py. Do not edit. */
:root {
  scrollbar-color: rgba(83,103,135, 0.7) transparent;
}
@-moz-document url("about:blank"), url("about:newtab"), url("about:home"), url("about:privatebrowsing") {
  html, body { background-color: #060f20 !important; }
}
